import 'package:dart_json_mapper/dart_json_mapper.dart' show JsonMapper, jsonSerializable;
import 'main.mapper.g.dart' show initializeJsonMapper;

@jsonSerializable
class MyData {
  int a = 123;
  MyData(this.a);
}

void main() {
  initializeJsonMapper();
  print(JsonMapper.serialize(MyData(456)));
}
